$sizes = @(16, 24, 32, 48, 64, 128, 256)

foreach ($sz in $sizes) {
    $scale = $sz / 512.0
    $canvas = New-Object System.Windows.Controls.Canvas
    $canvas.Width = $sz
    $canvas.Height = $sz
    $canvas.Background = [System.Windows.Media.Brushes]::Transparent

    $group = New-Object System.Windows.Media.TransformGroup
    $group.Children.Add([System.Windows.Media.ScaleTransform]::new($scale, $scale))
    $canvas.RenderTransform = $group

    foreach ($p in $svgPaths) {
        $pathObj = New-Object System.Windows.Shapes.Path
        $pathObj.Fill = [System.Windows.Media.BrushConverter]::new().ConvertFromString($p.Fill)
        $pathObj.Data = [System.Windows.Media.Geometry]::Parse($p.Data)
        $null = $canvas.Children.Add($pathObj)
    }

    $canvas.Measure([System.Windows.Size]::new($sz, $sz))
    $canvas.Arrange([System.Windows.Rect]::new(0, 0, $sz, $sz))
    $canvas.UpdateLayout()

    $rtb = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($sz, $sz, 96, 96, [System.Windows.Media.PixelFormats]::Pbgra32)
    $rtb.Render($canvas)

    $encoder = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
    $encoder.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($rtb))

    $outFile = "leaf-$sz.png"
    $fs = [System.IO.File]::OpenWrite($outFile)
    $encoder.Save($fs)
    $fs.Close()
    Write-Output "Generated $outFile"
}

